     3	public sealed class CashMachine(IMoneyDispenser dispenser) : ICashMachine
     4	{
     5	    private const int DailyLimit = 200;
     6	    private const int FeeThreshold = 100;
     7	    private const int WithdrawalFee = 5;
     8	    private const int CassetteCapacity = 5;
     9	    private const int MaxNotesPerPass = 4;
    10	
    11	    public AtmResult Execute(AccountState account, Operation operation) => operation switch
    12	    {
    13	        Operation.Withdraw withdraw => Withdraw(account, withdraw.Amount),
    14	        Operation.Deposit deposit => Deposit(account, deposit.Notes),
    15	        _ => throw new ArgumentException("Opération inconnue.", nameof(operation)),
    16	    };
    17	
    18	    private AtmResult Withdraw(AccountState account, int amount)
    19	    {
    20	        if (amount <= 0 || amount % 10 != 0)
    21	        {
    22	            return Refuse(AtmStatus.InvalidAmount, account);
    23	        }
    24	
    25	        if (account.WithdrawnToday + amount > DailyLimit)
    26	        {
    27	            return Refuse(AtmStatus.DailyLimitExceeded, account);
    28	        }
    29	
    30	        var fee = amount > FeeThreshold ? WithdrawalFee : 0;
    31	        if (amount + fee > account.Balance)
    32	        {
    33	            return Refuse(AtmStatus.InsufficientFunds, account);
    34	        }
    35	
    36	        if (FewestNotes(amount, Available()) is not { } combination)
    37	        {
    38	            return Refuse(AtmStatus.CannotDispense, account);
    39	        }
    40	
    41	        var dispensed = NoteCounts.None;
    42	        foreach (var pass in Passes(combination))
    43	        {
    44	            if (!dispenser.Dispense(pass))
    45	            {
    46	                return new AtmResult(AtmStatus.DispenserFault, dispensed, 0, account);
    47	            }
    48	
    49	            dispensed += pass;
    50	        }
    51	
    52	        var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);
    53	
    54	        return new AtmResult(AtmStatus.Ok, combination, fee, after);
    55	    }
    56	
    57	    private AtmResult Deposit(AccountState account, NoteCounts notes)
    58	    {
    59	        if (notes.Fifties < 0 || notes.Twenties < 0 || notes.Tens < 0 || notes.Total == 0)
    60	        {
    61	            return Refuse(AtmStatus.InvalidAmount, account);
    62	        }
    63	
    64	        if (dispenser.Jammed is { } jammed && notes.Of(jammed) > 0)
    65	        {
    66	            return Refuse(AtmStatus.CassetteJammed, account);
    67	        }
    68	
    69	        var after = dispenser.Stock + notes;
    70	        if (after.Fifties > CassetteCapacity || after.Twenties > CassetteCapacity || after.Tens > CassetteCapacity)
    71	        {
    72	            return Refuse(AtmStatus.CassetteFull, account);
    73	        }
    74	
    75	        if (!dispenser.Load(notes))
    76	        {
    77	            return Refuse(AtmStatus.DispenserFault, account);
    78	        }
    79	
    80	        return new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, account with { Balance = account.Balance + notes.Value });
    81	    }
    82	
    83	    private static AtmResult Refuse(AtmStatus status, AccountState account) =>
    84	        new(status, NoteCounts.None, 0, account);
    85	
    86	    /// <summary>Le stock utilisable : la cassette bloquée compte pour zéro.</summary>
    87	    private NoteCounts Available()
    88	    {
    89	        var stock = dispenser.Stock;
    90	
    91	        return dispenser.Jammed switch
    92	        {
    93	            Denomination.Fifty => stock with { Fifties = 0 },
    94	            Denomination.Twenty => stock with { Twenties = 0 },
    95	            Denomination.Ten => stock with { Tens = 0 },
    96	            _ => stock,
    97	        };
    98	    }
    99	
   100	    /// <summary>La combinaison qui fait exactement <paramref name="amount"/> avec le moins de billets, ou <c>null</c>.</summary>
   101	    private static NoteCounts? FewestNotes(int amount, NoteCounts available)
   102	    {
   103	        NoteCounts? best = null;
   104	        for (var fifties = Math.Min(available.Fifties, amount / 50); fifties >= 0; fifties--)
   105	        {
   106	            var afterFifties = amount - fifties * 50;
   107	            for (var twenties = Math.Min(available.Twenties, afterFifties / 20); twenties >= 0; twenties--)
   108	            {
   109	                var rest = afterFifties - twenties * 20;
   110	                if (rest % 10 != 0 || rest / 10 > available.Tens)
   111	                {
   112	                    continue;
   113	                }
   114	
   115	                var candidate = new NoteCounts(fifties, twenties, rest / 10);
   116	                if (best is not { } current || candidate.Total < current.Total)
   117	                {
   118	                    best = candidate;
   119	                }
   120	            }
   121	        }
   122	
   123	        return best;
   124	    }
   125	
   126	    /// <summary>Découpe la combinaison en passages de 4 billets au plus.</summary>
   127	    private static IEnumerable<NoteCounts> Passes(NoteCounts notes)
   128	    {
   129	        var remaining = notes;
   130	        while (remaining.Total > 0)
   131	        {
   132	            var room = MaxNotesPerPass;
   133	            var fifties = Math.Min(remaining.Fifties, room);
   134	            room -= fifties;
   135	            var twenties = Math.Min(remaining.Twenties, room);
   136	            room -= twenties;
   137	            var tens = Math.Min(remaining.Tens, room);
   138	
   139	            var pass = new NoteCounts(fifties, twenties, tens);
   140	            remaining -= pass;
   141	
   142	            yield return pass;
   143	        }
   144	    }
   145	}
